python
def xorRegisterThresholdFile(readings, k):
    a=readings
    out=[]
    state=0
    for x in a:
        state^=x
        out.append(state)
    return sum(x>=k for x in out)


java
class Solution {
  public int xorRegisterThresholdFile(int[] readings, int k) {
    int[] a=readings; List<Integer> out=new ArrayList<>();
    {int state=0;for(int x:a){state^=x;out.add(state);}}
    int answer=0;for(int x:out)if(x>=k)answer++;return answer;
  }
}
